head.script:
scwin.screenId = "uldmgt50314";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// [A] 초기 목록 미해결 — uldmgt50314: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'uldmgt50314.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.grd_helpManuals_2_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_helpManuals_2_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_helpManuals');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_helpManuals'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (columnId === "__rowAct") { if (typeof scwin.content === 'function') { scwin.content(r["manualId"]); } else { console.error('[sdd] 행 동작 미정의: scwin.content (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.content'); } return; } if (typeof scwin.modManual === 'function') { scwin.modManual(r["manualId"]); } else { console.error('[sdd] 행 동작 미정의: scwin.modManual (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.modManual'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_helpManuals_2.oncellclick' });
    }
};


///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @event
 * @name scwin.grd_helpManuals_2_fillAct
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.grd_helpManuals_2_fillAct = async function () {
    try {
        const dl = $c.util.getComponent('dlt_helpManuals');
        if (!dl || !dl.getTotalRow) { return; }
        for (let i = 0; i < dl.getTotalRow(); i++) {
            const r = dl.getRowJSON(i);
            const v = '-';
            if (r) {  }
            dl.setCellData(i, "__rowAct", v);
        }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_helpManuals_2.fillAct' });
    }
};

/**
 * @method
 * @name scwin.content
 * @author Inswave
 * @date 2026. 09. 29
 * @param manualId
 * @returns
 * @hidden N
*/
scwin.content = function (manualId) {
    /* sdd-asis-lifecycle:begin fn_Content — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const cobj = eval("document.all.manual_" + manualId);
    if (cobj.style.display === "none") {
        cobj.style.display = "block";
    } else {
        cobj.style.display = "none";
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.addManual
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.addManual = function () {
    /* sdd-asis-lifecycle:begin fn_AddManual — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.win.setPageFrameSrc($c.win.getFrame(), '/uldmgt50305/uldmgt50305.xml') + dma_pageContext.get("helpClssId") + "&mode=create";
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.modManual
 * @author Inswave
 * @date 2026. 09. 29
 * @param manualId
 * @returns
 * @hidden N
*/
scwin.modManual = function (manualId) {
    /* sdd-asis-lifecycle:begin fn_ModManual — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.win.setPageFrameSrc($c.win.getFrame(), '/uldmgt50305/uldmgt50305.xml') + manualId + "&mode=update";
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.delManual
 * @author Inswave
 * @date 2026. 09. 29
 * @param manualId title
 * @returns
 * @hidden N
*/
scwin.delManual = async function (manualId, title) {
    /* sdd-asis-lifecycle:begin fn_DelManual — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const _confirm = await $c.win.confirm("매뉴얼 '" + title + "'를\n삭제하시겠습니까?");
    if (!_confirm) {
        return;
    }
    $c.win.setPageFrameSrc($c.win.getFrame(), '/uldmgt50305/uldmgt50305.xml') + dma_pageContext.get("helpClssId") + "&manualId=" + manualId;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.close
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.close = function () {
    /* sdd-asis-lifecycle:begin close — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};
